// Normalize both payload shapes into one clean lead object.
// Website form: { name, email, message, source }
// Calendly (simplified): { name, email, event_time }
// Real Calendly webhooks nest data under `payload`, handled below too.

const body = $input.first().json.body || $input.first().json;
const p = body.payload || {};

const isCalendly = Boolean(body.event_time) || Boolean(p.scheduled_event) || body.event === 'invitee.created';

const name = body.name || p.name || 'there';
const email = body.email || p.email || '';
const eventTime = body.event_time || (p.scheduled_event ? p.scheduled_event.start_time : '') || '';
const message = body.message || '';
const source = body.source || (isCalendly ? 'calendly' : 'website_form');
const firstName = String(name).trim().split(/\s+/)[0] || 'there';
const fromName = $env.FROM_NAME || 'Me';

// --- Email copy lives here so it is easy to edit in ONE place. No em dashes. ---
let emailSubject;
let emailBody;

if (isCalendly) {
  emailSubject = `You're booked, ${firstName}!`;
  emailBody = `Hi ${firstName},\n\nJust saw your booking come through for ${eventTime}. That works great on my end, so we are all set.\n\nNo prep needed. If anything changes before then, just reply here and we can find another time.\n\nLooking forward to it,\n${fromName}`;
} else {
  emailSubject = `Got your message, ${firstName}`;
  emailBody = `Hi ${firstName},\n\nThanks for reaching out, I just read your note. Wanted to reply right away so you know it reached a real person.\n\nI will get back to you properly today. If it is urgent, reply to this email and I will bump you to the front of the line.\n\nTalk soon,\n${fromName}`;
}

return [{
  json: {
    name,
    first_name: firstName,
    email,
    source,
    message,
    event_time: eventTime,
    received_at: $now.toISO(),
    email_subject: emailSubject,
    email_body: emailBody
  }
}];

